  'For account-specific issues, use the in-app contact form so your request stays connected to your signed-in account.': 'للمشكلات الخاصة بحسابك، استخدم نموذج التواصل داخل التطبيق ليبقى الطلب مرتبطاً بحسابك المسجل.',
  'How do I get started?': 'كيف أبدأ؟',
  'Open My Workspace or Dashboard, choose an available tool, and follow the inputs shown for that tool. Website Builder V1 is available for creating and publishing responsive websites.': 'افتح مساحة عملي أو لوحة التحكم، واختر أداة متاحة واتبع الحقول المعروضة. منشئ المواقع V1 متاح لإنشاء مواقع متجاوبة ونشرها.',
  'Which interface languages are supported?': 'ما لغات الواجهة المدعومة؟',
  'The product interface supports English, Arabic, and Swedish. Arabic automatically uses right-to-left layout where appropriate.': 'تدعم واجهة المنتج الإنجليزية والعربية والسويدية، وتستخدم العربية اتجاه اليمين إلى اليسار تلقائياً حيث يلزم.',
  'How does Website Builder billing work?': 'كيف تعمل فوترة منشئ المواقع؟',
  'Free supports 1 website project with up to 3 pages. Pro supports up to 10 website projects and 25 pages per website. Business supports up to 50 website projects and 100 pages per website.': 'تدعم الخطة المجانية مشروع موقع واحد حتى 3 صفحات. تدعم Pro حتى 10 مشاريع و25 صفحة لكل موقع. تدعم Business حتى 50 مشروعاً و100 صفحة لكل موقع.',
  'Is my data protected?': 'هل بياناتي محمية؟',
  'The application uses authenticated access and database row-level security for account-scoped data. Always keep your account credentials private and review sensitive AI output before sharing it.': 'يستخدم التطبيق وصولاً موثقاً وأماناً على مستوى الصفوف للبيانات المرتبطة بالحساب. حافظ على بيانات دخولك خاصة وراجع مخرجات الذكاء الاصطناعي الحساسة قبل مشاركتها.',
  'How do I manage my subscription?': 'كيف أدير اشتراكي؟',
  'Open Subscription from the workspace menu. New upgrades use Stripe Checkout, and existing paid subscriptions can be managed through the Stripe billing portal.': 'افتح الاشتراك من قائمة مساحة العمل. تستخدم الترقيات الجديدة Stripe Checkout ويمكن إدارة الاشتراكات المدفوعة الحالية من بوابة Stripe.',
  'How do I report a bug?': 'كيف أبلغ عن خطأ؟',
  'Open Support and choose Report a Bug. Include the affected tool, severity, steps to reproduce, expected behavior, and actual behavior.': 'افتح الدعم واختر الإبلاغ عن خطأ، وأضف الأداة المتأثرة والخطورة وخطوات إعادة المشكلة والسلوك المتوقع والفعلي.',
