  'Plan full feature': 'تخطيط ميزة كاملة',
  'Combine up to {count} compatible components into one coherent integration pack. Use a starter preset or build a custom kit by selecting a component and pressing Add to kit.': 'ادمج ما يصل إلى {count} مكوّنات متوافقة في حزمة تكامل واحدة متناسقة. استخدم إعداداً جاهزاً أو أنشئ حزمة مخصصة باختيار مكوّن والضغط على «إضافة إلى الحزمة».',
  'Compose kit': 'تركيب الحزمة',
