  'Compose a complete page from ranked registry anchors instead of choosing components one by one. The generated pack reuses project style, supports a controlled theme direction and still goes through Preview, Dependency Review, Diff, Safe Apply and Rollback.': 'أنشئ صفحة كاملة من نقاط ارتكاز مرتبة في السجل بدلاً من اختيار المكوّنات واحداً تلو الآخر. تعيد الحزمة المنشأة استخدام أسلوب المشروع وتدعم اتجاهاً مضبوطاً للسمة، مع المرور بمعاينة ومراجعة التبعيات والفروقات والتطبيق الآمن والتراجع.',
  'Compose page': 'تركيب الصفحة',
  'Run a bounded project-wide static scan for accessibility, responsive layout, style consistency, motion handling, dependency noise and repeated UI patterns. Findings are produced locally before AI is involved.': 'شغّل فحصاً ثابتاً محدوداً على مستوى المشروع لإمكانية الوصول والتخطيط المتجاوب واتساق الأسلوب والحركة وضوضاء التبعيات وأنماط الواجهة المتكررة. يتم إنتاج النتائج محلياً قبل إشراك الذكاء الاصطناعي.',
