  'About Tayar Intelligence': 'Om Tayar Intelligence',
  'A focused workspace for building, creating, collaborating and shipping finished work.': 'En fokuserad arbetsyta för att bygga, skapa, samarbeta och leverera färdigt arbete.',
  'Tayar Intelligence brings practical productivity tools into one workspace. The current product includes Website Builder V1, team workspaces, document and writing tools, translation, study workflows, project management and account-level preferences.': 'Tayar Intelligence samlar praktiska produktivitetsverktyg i en arbetsyta. Produkten innehåller Webbplatsbyggare V1, teamarbetsytor, dokument- och skrivverktyg, översättning, studieflöden, projekthantering och kontoinställningar.',
  'The goal is simple: reduce tool switching while keeping the important parts of a project — content, versions, permissions and delivery — connected.': 'Målet är enkelt: minska växlingen mellan verktyg och samtidigt hålla viktiga projektdelar — innehåll, versioner, behörigheter och leverans — sammanlänkade.',
  'Website Builder V1': 'Webbplatsbyggare V1',
  'Website Builder V1 is active and supports responsive pages, forms, publishing, release history and rollback, multilingual pages, analytics, conversion tracking, lead management, team collaboration and client handoff workflows.': 'Webbplatsbyggare V1 är aktiv och stöder responsiva sidor, formulär, publicering, versionshistorik och återställning, flerspråkiga sidor, analys, konverteringsspårning, leadshantering, teamsamarbete och kundleverans.',
  'What comes next': 'Vad kommer härnäst',
  'The next major product phase is AI-assisted website generation. It is intentionally separate from V1 so the core builder can remain useful and production-ready without depending on AI generation.': 'Nästa större fas är AI-assisterad webbplatsgenerering. Den hålls avsiktligt separat från V1 så att kärnbyggaren förblir användbar och produktionsklar utan beroende av AI-generering.',
