  'Cookie settings': 'Cookie-inställningar',
  'Last updated: August 28, 2026': 'Senast uppdaterad: 28 augusti 2026',
  'Terms of Service': 'Användarvillkor',
  'This page describes the main categories of information Tayar Intelligence may process when you use the product. The exact data involved depends on the features you choose to use.': 'Den här sidan beskriver huvudkategorierna av information som Tayar Intelligence kan behandla när du använder produkten. Exakta data beror på vilka funktioner du använder.',
  'Account details, profile settings, projects, files, preferences and collaboration data may be stored so the service can authenticate you, save your work and enforce access permissions.': 'Kontouppgifter, profilinställningar, projekt, filer, preferenser och samarbetsdata kan lagras för autentisering, sparande av arbete och åtkomstkontroll.',
  'Website Builder projects can include pages, media references, form submissions, leads, analytics events, release history, publishing settings and team permissions. Public website forms and analytics use dedicated server-side controls and rate limits.': 'Projekt i Webbplatsbyggaren kan innehålla sidor, mediereferenser, formulärsvar, leads, analyshändelser, versionshistorik, publiceringsinställningar och teambehörigheter. Publika formulär och analys använder särskilda serverkontroller och hastighetsgränser.',
  'The application uses third-party infrastructure such as Supabase for authentication, database and storage capabilities. Features that use external AI or payment services may send the information required to complete that specific request to the configured provider.': 'Applikationen använder tredjepartsinfrastruktur som Supabase för autentisering, databas och lagring. Funktioner som använder externa AI- eller betaltjänster kan skicka den information som krävs för den specifika begäran till konfigurerad leverantör.',
  'The application uses encrypted network connections and database access controls, including Row Level Security for user and workspace data. Authentication credentials are handled through the authentication provider rather than being stored as plaintext application data.': 'Applikationen använder krypterade nätverksanslutningar och databasåtkomstkontroller, inklusive Row Level Security för användar- och arbetsytedata. Autentiseringsuppgifter hanteras av autentiseringsleverantören och lagras inte som klartext i appen.',
  'Browser storage may be used for authentication sessions, interface preferences, recovery data and consent choices. Analytics or production integrations are controlled by the relevant product and website settings.': 'Webbläsarlagring kan användas för autentiseringssessioner, gränssnittsinställningar, återställningsdata och samtyckesval. Analys- och produktionsintegrationer styrs av relevanta produkt- och webbplatsinställningar.',
  'You can manage account preferences and many stored project settings inside the product. Requests relating to access, correction or deletion of personal data should be made through the support options available in your account.': 'Du kan hantera kontoinställningar och många lagrade projektinställningar i produkten. Begäran om åtkomst, rättelse eller radering av personuppgifter ska göras via supportalternativen i ditt konto.',
  'This policy may be updated as the product, infrastructure or legal requirements change. The date at the top of this page shows the latest published revision.': 'Policyn kan uppdateras när produkten, infrastrukturen eller juridiska krav förändras. Datumet högst upp visar senaste publicerade revision.',
  'By using Tayar Intelligence, you agree to use the service lawfully and in a way that does not interfere with other users, the platform or its infrastructure.': 'Genom att använda Tayar Intelligence godkänner du att använda tjänsten lagligt och utan att störa andra användare, plattformen eller infrastrukturen.',
  'You are responsible for the accuracy of information submitted through your account and for keeping access to your account secure. Team and shared-project permissions should only be granted to people you intend to collaborate with.': 'Du ansvarar för riktigheten i information som skickas via ditt konto och för att hålla kontot säkert. Team- och projektbehörigheter ska bara ges till personer du avser att samarbeta med.',
  'You remain responsible for reviewing the content, websites, documents and other outputs you create or publish through the platform. Automated or AI-assisted output should be checked before it is relied on or published.': 'Du ansvarar fortsatt för att granska innehåll, webbplatser, dokument och andra resultat som du skapar eller publicerar via plattformen. Automatiskt eller AI-assisterat material ska kontrolleras innan det används eller publiceras.',
  'You may not use the service to break the law, abuse public forms or APIs, bypass product limits or access controls, distribute malicious content, interfere with the service, or attempt unauthorized access to other accounts or projects.': 'Du får inte använda tjänsten för att bryta mot lagen, missbruka publika formulär eller API:er, kringgå produktgränser eller åtkomstkontroller, sprida skadligt innehåll, störa tjänsten eller försöka få obehörig åtkomst till andra konton eller projekt.',
  'Free, Pro and Business features and usage limits are displayed in the product. Paid pricing, renewal details, cancellation options and any applicable billing terms are presented through the configured checkout and billing portal. Applicable consumer rights remain unaffected.': 'Funktioner och användningsgränser för Free, Pro och Business visas i produkten. Betald prissättning, förnyelse, uppsägning och tillämpliga faktureringsvillkor visas via konfigurerad checkout och faktureringsportal. Tillämpliga konsumenträttigheter påverkas inte.',
  'Features may evolve as the product is improved. We may change, add or retire features when needed for security, reliability or product development. Important changes should be reflected in the product or these terms.': 'Funktioner kan utvecklas när produkten förbättras. Vi kan ändra, lägga till eller ta bort funktioner när det behövs för säkerhet, tillförlitlighet eller produktutveckling. Viktiga ändringar ska återspeglas i produkten eller villkoren.',
  'The service is provided as a productivity platform. You are responsible for the final decisions, publications and actions taken using the outputs of the service, including websites published to third-party or configured hosting destinations.': 'Tjänsten tillhandahålls som en produktivitetsplattform. Du ansvarar för slutliga beslut, publiceringar och åtgärder som görs med tjänstens resultat, inklusive webbplatser som publiceras till tredje part eller konfigurerade hostingmål.',
  'Questions about these terms can be submitted through the support options available in the product.': 'Frågor om villkoren kan skickas via supportalternativen i produkten.',

