  'Share an idea or tell us what would make Tayar better.': 'Dela en idé eller berätta hur Tayar kan bli bättre.',
  'Report a reproducible problem with clear technical details.': 'Rapportera ett reproducerbart problem med tydliga tekniska detaljer.',
  'For account-specific issues, use the in-app contact form so your request stays connected to your signed-in account.': 'För kontospecifika problem, använd formuläret i appen så att ärendet kopplas till ditt inloggade konto.',
  'How do I get started?': 'Hur kommer jag igång?',
  'Open My Workspace or Dashboard, choose an available tool, and follow the inputs shown for that tool. Website Builder V1 is available for creating and publishing responsive websites.': 'Öppna Min arbetsyta eller Dashboard, välj ett tillgängligt verktyg och följ fälten som visas. Webbplatsbyggare V1 kan skapa och publicera responsiva webbplatser.',
  'Which interface languages are supported?': 'Vilka gränssnittsspråk stöds?',
  'The product interface supports English, Arabic, and Swedish. Arabic automatically uses right-to-left layout where appropriate.': 'Produktgränssnittet stöder engelska, arabiska och svenska. Arabiska använder automatiskt höger-till-vänster-layout där det behövs.',
  'How does Website Builder billing work?': 'Hur fungerar betalning för Webbplatsbyggaren?',
  'Free supports 1 website project with up to 3 pages. Pro supports up to 10 website projects and 25 pages per website. Business supports up to 50 website projects and 100 pages per website.': 'Free stöder 1 webbplatsprojekt med upp till 3 sidor. Pro stöder upp till 10 projekt och 25 sidor per webbplats. Business stöder upp till 50 projekt och 100 sidor per webbplats.',
  'Is my data protected?': 'Är mina data skyddade?',
  'The application uses authenticated access and database row-level security for account-scoped data. Always keep your account credentials private and review sensitive AI output before sharing it.': 'Appen använder autentiserad åtkomst och radnivåsäkerhet för kontodata. Håll alltid dina inloggningsuppgifter privata och granska känsligt AI-innehåll innan du delar det.',
  'How do I manage my subscription?': 'Hur hanterar jag min prenumeration?',
  'Open Subscription from the workspace menu. New upgrades use Stripe Checkout, and existing paid subscriptions can be managed through the Stripe billing portal.': 'Öppna Prenumeration i arbetsytans meny. Nya uppgraderingar använder Stripe Checkout och befintliga betalda prenumerationer hanteras i Stripes betalningsportal.',
  'How do I report a bug?': 'Hur rapporterar jag ett fel?',
  'Open Support and choose Report a Bug. Include the affected tool, severity, steps to reproduce, expected behavior, and actual behavior.': 'Öppna Support och välj Rapportera ett fel. Ange berört verktyg, allvarlighetsgrad, steg för att återskapa felet samt förväntat och faktiskt beteende.',
  'Failed to send support request. Please try again.': 'Kunde inte skicka supportärendet. Försök igen.',
